using System.IO;
using System.Text.Json;
using VisionPlugins.Calibration;
var decoder=System.Windows.Media.Imaging.BitmapDecoder.Create(new Uri(Path.GetFullPath("analysis/full-audit/n-image-calibration/solver-fixture/frame-0.bmp")),System.Windows.Media.Imaging.BitmapCreateOptions.PreservePixelFormat,System.Windows.Media.Imaging.BitmapCacheOption.OnLoad);var bitmap=new System.Windows.Media.Imaging.FormatConvertedBitmap(decoder.Frames[0],System.Windows.Media.PixelFormats.Gray8,null,0);var pixels=new byte[bitmap.PixelWidth*bitmap.PixelHeight];bitmap.CopyPixels(pixels,bitmap.PixelWidth,0);var gray=new VisionCore.GrayImage(bitmap.PixelWidth,bitmap.PixelHeight,pixels);var pitches=new Dictionary<int,float>();foreach(int board in new[]{7,9}){var detected=NImageBoardRecognition.Find(gray,board);if(detected is not null)pitches[board]=detected.GridPitch;Console.WriteLine(JsonSerializer.Serialize(new{phase="managed-detection",board,pitch=detected?.GridPitch,count=detected?.Points.Count,first=detected?.Points.FirstOrDefault()}));}
var path=Path.GetFullPath("analysis/map-calibration/native/image-results.jsonl");
foreach(var line in File.ReadLines(path)){using var d=JsonDocument.Parse(line);var r=d.RootElement;if(!r.TryGetProperty("source",out var s))continue;var source=s.EnumerateArray().Select(p=>p.EnumerateArray().Select(x=>x.GetDouble()).ToArray()).ToArray();var target=r.GetProperty("target").EnumerateArray().Select(p=>p.EnumerateArray().Select(x=>x.GetDouble()).ToArray()).ToArray();int model=r.GetProperty("model").GetInt32();var expected=r.GetProperty("matrix").EnumerateArray().Select(x=>x.GetDouble()).ToArray();if(!pitches.TryGetValue(r.GetProperty("board").GetInt32(),out float pitch)){Console.WriteLine(JsonSerializer.Serialize(new{phase="unsupported-managed-board",board=r.GetProperty("board").GetInt32(),model}));continue;}var options=new NPointSolveOptions(model,3);var a=NPointSolver.Solve(source.Select(p=>new NPointPair(p[0],p[1],(float)p[2]*pitch,(float)p[3]*pitch)).ToArray(),[],options);var b=NPointSolver.Solve(target.Select(p=>new NPointPair(p[0],p[1],(float)p[2]*pitch,(float)p[3]*pitch)).ToArray(),[],options);var direct=NPointSolver.Solve(source.Zip(target).Select(p=>new NPointPair(p.First[0],p.First[1],p.Second[0],p.Second[1])).ToArray(),[],options);var sourceFloat=a.Matrix.Select(v=>(float)v/(float)(a.Matrix[8]+1.1920928955078125e-7f)).ToArray();var targetFloat=b.Matrix.Select(v=>(float)v/(float)(b.Matrix[8]+1.1920928955078125e-7f)).ToArray();var actualFloat=VisionPlugins.MapCalibration.MapCalibrationSolver.SolveFiles(sourceFloat,targetFloat);var composed=Multiply(Inverse(b.Matrix),a.Matrix);Console.WriteLine(JsonSerializer.Serialize(new{model,board=r.GetProperty("board").GetInt32(),directMax=Max(expected,direct.Matrix),composedMax=Max(expected,composed),direct=direct.Matrix,floatMax=Max(expected,actualFloat.Matrix.Select(v=>(double)v).ToArray()),floatComposed=actualFloat.Matrix,composed}));}
static double Max(double[]a,double[]b)=>a.Zip(b).Max(x=>Math.Abs(x.First-x.Second));
static double[] Multiply(double[]a,double[]b)=>Enumerable.Range(0,9).Select(i=>Enumerable.Range(0,3).Sum(k=>a[i/3*3+k]*b[k*3+i%3])).ToArray();
static double[] Inverse(double[]a){double det=a[0]*(a[4]*a[8]-a[5]*a[7])-a[1]*(a[3]*a[8]-a[5]*a[6])+a[2]*(a[3]*a[7]-a[4]*a[6]);return new[]{a[4]*a[8]-a[5]*a[7],a[2]*a[7]-a[1]*a[8],a[1]*a[5]-a[2]*a[4],a[5]*a[6]-a[3]*a[8],a[0]*a[8]-a[2]*a[6],a[2]*a[3]-a[0]*a[5],a[3]*a[7]-a[4]*a[6],a[1]*a[6]-a[0]*a[7],a[0]*a[4]-a[1]*a[3]}.Select(v=>v/det).ToArray();}




